// _mutation_resetSliceShardPlacement empties the []shard.Placement that x
// points at and resets every element of its capacity, which keeps its memory
// for the next decode.
func _mutation_resetSliceShardPlacement(x *[]shard.Placement) {
	s := (*x)[:cap(*x)]
	for k := range s {
		s[k].Reset()
	}
	*x = (*x)[:0]
}

